#![allow(clippy::all)]
use crate::keyframe::{
    AnimationDefinition, Channel,
    Interpolation::{self, CatmullRom, Linear},
    Keyframe, Target,
};
use glam::Vec3;
use std::sync::LazyLock;
fn k(t: f32, pre: [f32; 3], post: [f32; 3], i: Interpolation) -> Keyframe {
    Keyframe {
        timestamp: t,
        pre: Vec3::from(pre),
        post: Vec3::from(post),
        interpolation: i,
    }
}

